/// Days in the month containing `y`/`m` (1-based month).
pub fn days_in_month(y: i64, m: i64) -> i64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        // The full Gregorian rule, not the every-four-years approximation: 2100 is NOT a leap year,
        // and a calendar that says a bill falls on 29 February 2100 is simply wrong.
        2 if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 => 29,
        2 => 28,
        _ => 30,
    }
}
